-- DisplayScale 0.5: the Eye Tentacle model renders too tall at native size (CreatureDisplayInfo
-- 15788 creatureModelScale 1.0 x CreatureModelData 2226 ModelScale 1.0, collision height 2.03).
-- This is the only server-side scale lever - Creature::GetNativeObjectScale() returns exactly this
-- value into OBJECT_FIELD_SCALE_X. It also halves the derived bounding radius / combat reach,
-- which is inert here (the tentacle is unselectable, unattackable and never melees).
DELETE FROM `creature_template_model` WHERE `CreatureID` = 300102;
INSERT INTO `creature_template_model` (`CreatureID`, `Idx`, `CreatureDisplayID`, `DisplayScale`, `Probability`, `VerifiedBuild`) VALUES
(300102, 0, 15788, 0.5, 1, 0);
